/* @autogenerated */
import { TestBed } from '@angular/core/testing';
import { DefaultUrlSerializer, Router } from '@angular/router';
import { IdentityService } from '@shared/context/identity/identity.service';
import { AuthorizationAccessService } from '@shared/context/authorization-access/authorization-access.service';
import { LandingComponent } from './landing.component';

describe('LandingComponent', () => {
  let identity: jasmine.SpyObj<IdentityService>;
  let access: jasmine.SpyObj<AuthorizationAccessService>;
  let url: string;

  const create = () => {
    const serializer = new DefaultUrlSerializer();
    TestBed.configureTestingModule({
      imports: [LandingComponent],
      providers: [
        { provide: IdentityService, useValue: identity },
        { provide: AuthorizationAccessService, useValue: access },
        {
          provide: Router,
          useValue: {
            get url() {
              return url;
            },
            parseUrl: (u: string) => serializer.parse(u),
          },
        },
      ],
    });
    TestBed.overrideComponent(LandingComponent, { set: { template: '', imports: [] } });
    const fixture = TestBed.createComponent(LandingComponent);
    fixture.detectChanges();
    return fixture.componentInstance;
  };

  beforeEach(() => {
    identity = jasmine.createSpyObj<IdentityService>('IdentityService', ['login']);
    access = jasmine.createSpyObj<AuthorizationAccessService>('AuthorizationAccessService', ['remember']);
    url = '/en/main';
  });

  afterEach(() => TestBed.resetTestingModule());

  it('signs in without remembering a route when nobody sent it here', () => {
    create().login();

    expect(access.remember).not.toHaveBeenCalled();
    expect(identity.login).toHaveBeenCalledWith('main');
  });

  it('comes back to the protected route that sent it here after signing in', () => {
    url = '/unauthorized?returnUrl=%2Fen%2Fmain%2Fusers&reason=401';
    create().login();

    expect(access.remember).toHaveBeenCalledWith('/en/main/users');
    expect(identity.login).toHaveBeenCalledWith('main');
  });
});
